#!/usr/bin/env bash
set -euo pipefail

ROOT="/workspaces/StormTracker"
cd "$ROOT"

echo "StormTracker — Core V4 sync/fallback fix"

for f in frontend/src/live3d-core-v3.js frontend/live3d-core-v3.html; do
  if [ ! -f "$f" ]; then echo "ERROR: Missing required file: $f"; exit 1; fi
done

cp frontend/src/live3d-core-v3.js frontend/src/live3d-core-v4.js
cp frontend/live3d-core-v3.html frontend/live3d-core-v4.html

cat > /tmp/stormtracker_replace_b64.py <<'PY'
import base64, sys
from pathlib import Path
path=Path(sys.argv[1]); mode=sys.argv[2]
old=base64.b64decode(sys.argv[3]).decode()
new=base64.b64decode(sys.argv[4]).decode()
text=path.read_text(encoding='utf-8')
count=text.count(old)
if count == 0:
    raise SystemExit(f'ERROR: patch target not found in {path}: {old[:80]!r}')
if mode == 'once':
    text=text.replace(old,new,1)
elif mode == 'all':
    text=text.replace(old,new)
else:
    raise SystemExit('bad mode')
path.write_text(text,encoding='utf-8')
print(f'{path}: replaced {1 if mode=="once" else count} occurrence(s)')
PY

